// ── WORKSHOP SEARCH ──
// Searches every Workshop entry, across all category subpages. The index
// (#wkIndex) is generated by scripts/build-workshop.js: title, type, meta,
// category and keywords taken from each guide's title, description and
// headings. Every typed word must start a word in the entry (so "TEG"
// doesn't match "strategy"); entries matching in the title rank first.
(function () {
  const $ = id => document.getElementById(id);
  const input = $('wkQuery'), results = $('wkResults'), overview = $('wkOverview'), status = $('wkStatus');
  const data = $('wkIndex');
  if (!input || !results || !overview || !data) return;

  const words = s => s.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').split(/[^a-z0-9]+/).filter(Boolean);
  const items = JSON.parse(data.textContent).map(i => ({
    ...i,
    title: words(i.t),
    all: words([i.t, i.y, i.m, i.c, i.k].join(' ')),
  }));
  const hits = (tokens, term) => tokens.some(t => t.startsWith(term));

  function el(tag, cls, text) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }

  function render(list) {
    results.textContent = '';
    list.slice(0, 60).forEach(i => {
      const a = el('a', 'post-row workshop-row');
      a.href = i.h;
      const info = el('div', 'post-info');
      info.append(el('div', 'post-type workshop-type', i.c + ' · ' + i.y), el('div', 'post-title', i.t), el('div', 'post-meta', i.m));
      a.append(info, el('span', 'post-arrow', '›'));
      results.appendChild(a);
    });
  }

  function search() {
    const terms = words(input.value);
    if (!terms.length) {
      results.hidden = true;
      overview.hidden = false;
      status.textContent = '';
      return;
    }
    const found = items
      .filter(i => terms.every(t => hits(i.all, t)))
      .map(i => ({ i, score: terms.filter(t => hits(i.title, t)).length }))
      .sort((a, b) => b.score - a.score)
      .map(x => x.i);
    overview.hidden = true;
    results.hidden = found.length === 0;
    render(found);
    status.textContent = found.length === 0 ? 'Nothing matches. Try a shorter word.'
      : found.length === 1 ? '1 result' : found.length + ' results';
  }

  input.addEventListener('input', search);
  input.addEventListener('keydown', e => { if (e.key === 'Escape') { input.value = ''; search(); } });
  // A ?q= link (or the browser's back button) restores the search.
  const q = new URLSearchParams(location.search).get('q');
  if (q) input.value = q;
  if (input.value) search();
})();
